  const F=[1,0,dt,0,0,1,0,dt,0,0,1,0,0,0,0,1],FP=new Array(16).fill(0),next=new Array(16).fill(0);
  for(let r=0;r<4;r++)for(let c=0;c<4;c++)for(let k=0;k<4;k++)FP[r*4+c]+=F[r*4+k]*P[k*4+c];
