    const s=Math.max(1e-3,Number(cov.velocitySigmaMps)||1e-3),R=s*s;updates.push(asmCueScalarUpdateA(q,[0,0,1,0],vel.x,R));updates.push(asmCueScalarUpdateA(q,[0,0,0,1],vel.y,R));
